// ====================================================
// FITBOT - ASISTENTE VIRTUAL FOCUS POWER FIT
// n8n - Code (JavaScript)
// Modo: Run Once for All Items
// ====================================================

// CONFIGURACIÓN DEL GIMNASIO

const GIMNASIO = {
  nombre: "Focus Power Fit",
  chatbot: "FitBot",

  sucursales: {
    reina: {
      nombre: "La Reina",
      direccion: "Carlos Silva Vildósola 9326, local 20, segundo piso",
      comuna: "La Reina, Santiago"
    },
    penalolen: {
      nombre: "Peñalolén",
      direccion: "Las Perdices 2990, local 37, segundo piso",
      comuna: "Peñalolén, Santiago"
    }
  }
};

// FUNCIONES DE TEXTO

function normalizar(valor) {
  return String(valor ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[¿?¡!.,;:()]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function contiene(texto, ...frases) {
  return frases.some(frase =>
    texto.includes(normalizar(frase))
  );
}

function palabra(texto, ...palabras) {
  return palabras.some(p => {
    const buscada = normalizar(p);
    return (` ${texto} `).includes(` ${buscada} `);
  });
}

// FORMATO DE UBICACIONES

function enlaceMaps(sucursal) {
  const ubicacion =
    `${sucursal.direccion}, ${sucursal.comuna}`;

  return (
    "https://www.google.com/maps/search/?api=1&query=" +
    encodeURIComponent(ubicacion)
  );
}

function mostrarSucursal(sucursal) {
  const maps = enlaceMaps(sucursal);

  return (
    `📍 *SUCURSAL ${sucursal.nombre.toUpperCase()}*\n\n` +
    `🏢 Dirección: ${sucursal.direccion}\n` +
    `📌 Comuna: ${sucursal.comuna}\n\n` +
    `🗺️ [Ver ubicación en Google Maps](${maps})\n\n` +
    `💪 ¡Te esperamos en Focus Power Fit!`
  );
}

// MENÚ PRINCIPAL

function menuPrincipal() {
  return (
    "¡Hola! 👋💪 Bienvenido a Focus Power Fit.\n\n" +
    "Soy FitBot, el asistente virtual de Focus Power Fit.\n\n" +
    "Puedo ayudarte con:\n\n" +
    "📍 Sucursales y ubicaciones\n" +
    "💪 Planes y entrenamientos\n" +
    "📆 Horarios y reservas\n" +
    "✅ Asistencias\n" +
    "⏰ Profesores y recuperación de sesiones\n" +
    "❌ Cancelaciones\n" +
    "❄️ Congelamiento de planes\n" +
    "📄 Contratos\n" +
    "💳 Pagos y precios\n\n" +
    "¿En qué puedo ayudarte?"
  );
}

// MOTOR DE RESPUESTAS

function responder(mensaje) {
  const texto = normalizar(mensaje);

  if (!texto) {
    return menuPrincipal();
  }

  // 1. PROFESOR AUSENTE O ATRASADO

  const mencionaProfesor = contiene(
    texto,
    "profesor", "profesora", "profe",
    "entrenador", "entrenadora",
    "coach", "instructor"
  );

  const problemaProfesor = contiene(
    texto,
    "no llega", "no llego",
    "no vino", "no viene",
    "no aparece", "no asiste",
    "no asistio", "falto",
    "llega tarde", "llego tarde",
    "se atraso", "se retrasa",
    "retraso", "atraso",
    "demora", "ausente",
    "no se presento"
  );

  if (
    mencionaProfesor && problemaProfesor
  ) {
    return (
      "⏰ *Recuperación de sesiones*\n\n" +
      "Si tu profesor no asiste o se retrasa " +
      "más de 20 minutos, puedes recuperar " +
      "la sesión según las condiciones de tu contrato.\n\n" +
      "💪 Comunícate con Focus Power Fit para " +
      "coordinar la recuperación."
    );
  }

  // 2. CANCELACIONES

  if (
    contiene(
      texto,
      "cancel", "anular",
      "no puedo asistir",
      "no podre ir",
      "no puedo ir",
      "no voy a ir",
      "faltar a mi clase",
      "avisar que no voy",
      "suspender una clase"
    )
  ) {
    return (
      "📅 *Cancelación de sesiones*\n\n" +
      "Debes avisar con al menos " +
      "6 horas hábiles de anticipación " +
      "para cancelar una sesión, " +
      "según las condiciones de tu contrato.\n\n" +
      "Para gestionar la cancelación, " +
      "contacta al personal del gimnasio."
    );
  }

  // 3. CONGELAMIENTO Y EXTENSIÓN

  if (
    contiene(
      texto,
      "congel", "pausar",
      "suspender mi plan",
      "extender mi plan",
      "extension del plan",
      "prorrogar",
      "enfermedad", "embarazo",
      "accidente", "viaje"
    )
  ) {
    return (
      "❄️ *Congelamiento y extensión de planes*\n\n" +
      "Los planes PT pueden congelarse " +
      "por motivos justificados, como:\n\n" +
      "• Enfermedad\n" +
      "• Accidente\n" +
      "• Embarazo\n" +
      "• Viajes\n\n" +
      "También pueden extenderse cuando " +
      "corresponda, presentando la " +
      "documentación requerida.\n\n" +
      "Consulta los requisitos con el gimnasio."
    );
  }

  // 4. SUCURSALES Y UBICACIONES

  if (
    contiene(
      texto,
      "sucursal", "sucursales",
      "ubicacion", "ubicaciones",
      "direccion", "direcciones",
      "donde estan", "donde quedan",
      "donde se ubican",
      "como llego", "como llegar",
      "donde esta el gimnasio",
      "donde queda el gimnasio",
      "la reina", "penalolen",
      "las perdices", "carlos silva"
    )
  ) {
    const pideReina = contiene(
      texto,
      "la reina", "carlos silva"
    );

    const pidePenalolen = contiene(
      texto,
      "penalolen", "las perdices"
    );

    if (pideReina && !pidePenalolen) {
      return mostrarSucursal(GIMNASIO.sucursales.reina);
    }

    if (pidePenalolen && !pideReina) {
      return mostrarSucursal(GIMNASIO.sucursales.penalolen);
    }

    return (
      "📍 *Nuestras sucursales*\n\n" +
      mostrarSucursal(GIMNASIO.sucursales.reina) +
      "\n\n--------------------\n\n" +
      mostrarSucursal(GIMNASIO.sucursales.penalolen) +
      "\n\n¿Cuál te gustaría visitar?"
    );
  }

  // 5. PRECIOS Y PROMOCIONES

  if (
    contiene(
      texto,
      "precio", "precios",
      "valor", "valores",
      "cuanto cuesta",
      "cuanto sale",
      "tarifa", "promocion",
      "descuento", "oferta",
      "mensualidad"
    )
  ) {
    return (
      "💰 *Precios y promociones*\n\n" +
      "Focus Power Fit ofrece entrenamiento " +
      "personalizado individual y compartido.\n\n" +
      "Los valores y promociones deben " +
      "confirmarse directamente con el gimnasio, " +
      "ya que pueden variar según el plan."
    );
  }

  // 6. PAGOS

  if (
    contiene(
      texto,
      "pagar", "pago", "pagos",
      "webpay", "mercado pago",
      "tarjeta", "transferencia",
      "medio de pago",
      "pago online", "pago en linea"
    )
  ) {
    return (
      "💳 *Información sobre pagos*\n\n" +
      "Actualmente, la plataforma de " +
      "Focus Power Fit no permite " +
      "realizar pagos online.\n\n" +
      "Para conocer los medios de pago " +
      "disponibles, consulta directamente " +
      "con el gimnasio."
    );
  }

  // 7. ASISTENCIAS

  if (
    contiene(
      texto,
      "asistencia", "asistencias",
      "marcar asistencia",
      "registrar asistencia",
      "control de asistencia",
      "registro de asistencia"
    )
  ) {
    return (
      "✅ *Registro de asistencia*\n\n" +
      "Focus Power Fit contempla el " +
      "registro de asistencia en el mesón " +
      "o mediante el sistema.\n\n" +
      "Para consultar una asistencia " +
      "específica, ingresa a tu cuenta " +
      "o solicita ayuda al personal autorizado."
    );
  }

  // 8. HORARIOS Y RESERVAS

  if (
    contiene(
      texto,
      "horario", "horarios",
      "reservar", "reserva",
      "agendar", "agendamiento",
      "disponibilidad",
      "mi clase", "mis clases",
      "mi sesion", "mis sesiones",
      "cuando entreno",
      "cambiar mi hora"
    )
  ) {
    return (
      "📆 *Horarios y reservas*\n\n" +
      "Puedes consultar tus horarios " +
      "y sesiones asignadas mediante " +
      "la plataforma, según las " +
      "funcionalidades habilitadas.\n\n" +
      "Para confirmar o modificar una reserva, " +
      "contacta al gimnasio."
    );
  }

  // 9. CONTRATOS

  if (
    contiene(
      texto,
      "contrato", "contratos",
      "clausula", "reglamento",
      "terminos", "condiciones"
    )
  ) {
    return (
      "📄 *Contratos*\n\n" +
      "Los contratos de Focus Power Fit " +
      "establecen las condiciones del servicio, " +
      "incluidas las asistencias, cancelaciones, " +
      "congelamientos y recuperación de sesiones.\n\n" +
      "Para revisar una cláusula específica, " +
      "consulta tu contrato o al personal autorizado."
    );
  }

  // 10. PLANES Y ENTRENAMIENTOS

  if (
    contiene(
      texto,
      "plan", "planes",
      "entrenamiento",
      "entrenar",
      "personal training",
      "personalizado",
      "individual",
      "compartido",
      "personal trainer",
      "inscripcion",
      "inscribirme",
      "que servicios ofrecen"
    )
  ) {
    return (
      "💪 *Planes y entrenamientos*\n\n" +
      "Focus Power Fit ofrece servicios " +
      "de entrenamiento personalizado (PT).\n\n" +
      "Las modalidades disponibles incluyen:\n\n" +
      "• Entrenamiento individual\n" +
      "• Entrenamiento compartido\n\n" +
      "Para conocer planes, cupos y " +
      "valores vigentes, comunícate " +
      "directamente con el gimnasio."
    );
  }

  // 11. AGRADECIMIENTOS

  if (
    contiene(
      texto,
      "gracias",
      "muchas gracias",
      "te agradezco"
    )
  ) {
    return (
      "¡De nada! 😊💪\n\n" +
      "Gracias por comunicarte con Focus Power Fit.\n" +
      "¿Necesitas ayuda con algo más?"
    );
  }

  // 12. DESPEDIDAS

  if (
    palabra(
      texto,
      "adios", "chao", "chau",
      "hasta luego", "nos vemos"
    )
  ) {
    return (
      "¡Hasta pronto! 👋💪\n\n" +
      "Gracias por comunicarte con Focus Power Fit."
    );
  }

  // 13. SALUDOS

  if (
    palabra(
      texto,
      "hola", "buenas",
      "hey", "holi", "holaa"
    ) ||
    contiene(
      texto,
      "buenos dias",
      "buenas tardes",
      "buenas noches"
    )
  ) {
    return menuPrincipal();
  }

  // 14. RESPUESTA PREDETERMINADA

  return (
    "🤖 Soy FitBot, el asistente virtual de Focus Power Fit.\n\n" +
    "Puedo ayudarte con sucursales, planes, " +
    "entrenamientos, horarios, asistencias, " +
    "cancelaciones, contratos y pagos.\n\n" +
    "¿Podrías contarme un poco más sobre tu consulta?"
  );
}

// RESPUESTA PARA N8N CHAT TRIGGER

return $input.all().map(item => {
  const mensaje =
    item.json.chatInput ??
    item.json.message ??
    item.json.text ??
    "";

  return {
    json: {
      output: responder(mensaje)
    }
  };
});
